package in.finseq.insurance;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;
public class DisplaySettingsActivity extends FinseqActivity{
 LinearLayout root;public void onCreate(Bundle b){super.onCreate(b);render();}
 void render(){root=Ui.column(this);Ui.appHeader(root,this,"Display Settings");LinearLayout body=Ui.contentColumn(this);root.addView(body);body.addView(Ui.text(this,"Theme",20,true));
 String[] choices={"System Default","Light","Dark"};String[] values={"system","light","dark"};String current=AppPrefs.theme(this);
 for(int i=0;i<choices.length;i++){final String value=values[i];LinearLayout row=Ui.actionRow(this,"◉",choices[i],current.equals(value)?"Selected":"Tap to use this theme");row.setOnClickListener(new View.OnClickListener(){public void onClick(View v){AppPrefs.theme(DisplaySettingsActivity.this,value);recreate();}});body.addView(row);}
 Button lang=Ui.outlineButton(this,"Language: "+(AppPrefs.language(this).equals("hi")?"हिन्दी → English":"English → हिन्दी"));body.addView(lang);body.addView(Ui.text(this,"Font Size",17,true));String[] labels={"Small Font","Normal Font","Large Font","Extra Large Font"};float[] sizes={0.88f,1f,1.12f,1.25f};for(int i=0;i<labels.length;i++){final float size=sizes[i];Button button=Ui.outlineButton(this,labels[i]);button.setOnClickListener(new View.OnClickListener(){public void onClick(View v){AppPrefs.fontScale(DisplaySettingsActivity.this,size);recreate();}});body.addView(button);}lang.setOnClickListener(new View.OnClickListener(){public void onClick(View v){final String next=AppPrefs.language(DisplaySettingsActivity.this).equals("hi")?"en":"hi";AppPrefs.language(DisplaySettingsActivity.this,next);Ui.run(DisplaySettingsActivity.this,new Runnable(){public void run(){try{ApiClient.post(DisplaySettingsActivity.this,"/api/v1/language",new org.json.JSONObject().put("language",next));}catch(Exception ignored){}}});recreate();}});setContentView(Ui.scroll(this,root));}
}
